import{_ as a,o as n,a as p,b as c}from"./app.C41L12d5.js";const l="/ascendc.github.io/assets/single_operator_api_execution_interface_call_flow.DbyBRmyA.png",_=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"调用","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/invocation/single_operator_api_call"},{"text":"单算子API调用","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/invocation/single_operator_api_call"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/invocation/single_operator_api_call.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/invocation/single_operator_api_call.md","outlineHeaders":[{"level":2,"title":"调用前检查","slug":"调用前检查","link":"#调用前检查"},{"level":2,"title":"基本原理","slug":"基本原理","link":"#基本原理"},{"level":2,"title":"准备调用工程","slug":"准备调用工程","link":"#准备调用工程"},{"level":2,"title":"单算子调用流程","slug":"单算子调用流程","link":"#单算子调用流程"},{"level":3,"title":"包含头文件并准备检查宏","slug":"包含头文件并准备检查宏","link":"#包含头文件并准备检查宏"},{"level":3,"title":"初始化运行环境","slug":"初始化运行环境","link":"#初始化运行环境"},{"level":3,"title":"准备输入输出数据并创建Tensor","slug":"准备输入输出数据并创建Tensor","link":"#准备输入输出数据并创建Tensor"},{"level":3,"title":"调用两段式接口","slug":"调用两段式接口","link":"#调用两段式接口"},{"level":3,"title":"拷贝结果并释放资源","slug":"拷贝结果并释放资源","link":"#拷贝结果并释放资源"},{"level":2,"title":"编译与运行","slug":"编译与运行","link":"#编译与运行"},{"level":3,"title":"CMakeLists.txt关键配置","slug":"CMakeLists.txt关键配置","link":"#CMakeLists.txt关键配置"},{"level":3,"title":"编译运行步骤","slug":"编译运行步骤","link":"#编译运行步骤"},{"level":2,"title":"常见问题","slug":"常见问题","link":"#常见问题"},{"level":2,"title":"进阶：API参数命名规则","slug":"进阶：API参数命名规则","link":"#进阶：API参数命名规则"},{"level":2,"title":"相关文档","slug":"相关文档","link":"#相关文档"}],"lastUpdated":1787050286000}'),e={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/invocation/single_operator_api_call.md"};function t(o,s,i,d,h,r){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>单算子API调用</h1><p>本文是基础内容，介绍单算子API调用——即通过C/C++调用aclnn接口完成异构计算的过程。aclnn接口和实现已经随自定义算子包交付，因此调用前需要先完成自定义算子包部署。运行时需要可用NPU环境；计算过程中使用的输入输出Tensor、Device内存、workspace、stream等资源由调用方负责申请和释放。</p><h2 id="调用前检查">调用前检查<a class="header-anchor" href="#调用前检查">​</a></h2><p>调用单算子API前，先确认以下条件已经满足：</p><ul><li><p>调用算子的运行环境有NPU设备。</p></li><li><p>完成自定义算子工程的创建。</p></li><li><p>完成算子原型定义、核函数（Kernel）侧实现和Host侧Tiling实现。</p></li><li><p>对于算子包编译场景，参考<a href="../compilation_and_deployment/basic_process.html">算子工程编译与部署</a>完成算子包的编译部署。算子二进制编译开关<code>ENABLE_BINARY_PACKAGE</code>默认开启；如果工程中显式设置为<code>False</code>，需要改为<code>True</code>后重新编译部署。</p><p>算子编译部署后，会在算子包安装目录下的<code>op_api</code>目录生成单算子调用的头文件<code>aclnn_&lt;op&gt;.h</code>和动态库<code>libcust_opapi.so</code>。</p><p>以默认安装场景为例，单算子调用的头文件和动态库所在的目录结构如下所示：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>├── opp    //算子库目录
│   ├── vendors     //自定义算子所在目录
│       ├── config.ini
│       └── vendor_name   // 存储对应厂商部署的自定义算子，此名字为编译自定义算子安装包时配置的vendor_name，若未配置，默认值为customize
│           ├── op_api
│           │   ├── include
│           │   │  └── aclnn_xx.h
│           │   └── lib
│           │       └── libcust_opapi.so
...
</code></pre></div></li><li><p>对于算子动态库或静态库编译场景，参考<a href="../compilation_and_deployment/dynamic_static_lib_compilation.html">算子动态库和静态库编译</a>完成算子的编译安装。其中<code>CMAKE_INSTALL_PREFIX</code>为开发者在cmake文件中配置的安装路径。</p><ul><li>动态库路径：<code>\${CMAKE_INSTALL_PREFIX}/lib/libcust_opapi.so</code></li><li>静态库路径：<code>\${CMAKE_INSTALL_PREFIX}/lib/lib\${vendor_name}.a</code></li><li>头文件路径：<code>\${CMAKE_INSTALL_PREFIX}/include</code></li></ul></li></ul><h2 id="基本原理">基本原理<a class="header-anchor" href="#基本原理">​</a></h2><p>完成自定义算子编译后，算子工程会基于算子原型定义自动生成单算子API头文件<code>aclnn_&lt;op&gt;.h</code>，并编译生成单算子API动态库<code>libcust_opapi.so</code>。调用时导入该头文件、链接该动态库后，就可以直接调用自定义算子。</p><p>单算子API一般是“两段式接口”：</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">aclnnStatus</span><span class="w"> </span><span class="nf">aclnnXxxGetWorkspaceSize</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">aclTensor</span><span class="w"> </span><span class="o">*</span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="p">...,</span><span class="w"> </span><span class="n">aclTensor</span><span class="w"> </span><span class="o">*</span><span class="n">out</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="o">*</span><span class="n">workspaceSize</span><span class="p">,</span><span class="w"> </span><span class="n">aclOpExecutor</span><span class="w"> </span><span class="o">**</span><span class="n">executor</span><span class="p">);</span>
<span class="n">aclnnStatus</span><span class="w"> </span><span class="nf">aclnnXxx</span><span class="p">(</span><span class="kt">void</span><span class="w"> </span><span class="o">*</span><span class="n">workspace</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">workspaceSize</span><span class="p">,</span><span class="w"> </span><span class="n">aclOpExecutor</span><span class="w"> </span><span class="o">*</span><span class="n">executor</span><span class="p">,</span><span class="w"> </span><span class="n">aclrtStream</span><span class="w"> </span><span class="n">stream</span><span class="p">);</span>
</code></pre></div><p>其中：</p><ul><li><code>aclnnXxxGetWorkspaceSize</code>是第一段接口，用于计算本次调用需要的workspace大小，按照workspaceSize申请NPU内存。</li><li><code>aclnnXxx</code>是第二段接口，使用第一段接口得到的<code>workspaceSize</code>、<code>executor</code>以及调用方申请的workspace，在指定stream上执行实际计算。</li><li><code>Xxx</code>来自算子原型注册时传入的算子类型。例如AddCustom算子生成的接口名为<code>aclnnAddCustomGetWorkspaceSize</code>和<code>aclnnAddCustom</code>。</li></ul><h2 id="准备调用工程">准备调用工程<a class="header-anchor" href="#准备调用工程">​</a></h2><p>本节以<a href="../aclnn_quick_start.html">AddCustom自定义算子</a>调用为例，介绍如何编写单算子调用的代码逻辑。其他算子的调用逻辑与AddCustom算子类似，请根据实际情况自行修改代码。该工程包含两个文件：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>├── CMakeLists.txt    // 编译规则文件
├── main.cpp          // 单算子调用主体流程实现文件
</code></pre></div><p>以下是关键步骤的代码示例，不可以直接拷贝编译运行，仅供参考，调用接口后，需增加异常处理的分支，并记录报错日志、提示日志，此处不一一列举。</p><h2 id="单算子调用流程">单算子调用流程<a class="header-anchor" href="#单算子调用流程">​</a></h2><p>单算子API执行流程如下：</p><p><strong>图1</strong> 单算子API执行接口调用流程。 <img src="`+l+`" alt title="单算子API执行接口调用流程"></p><h3 id="包含头文件并准备检查宏">包含头文件并准备检查宏<a class="header-anchor" href="#包含头文件并准备检查宏">​</a></h3><p>调用程序需要包含CANN运行时头文件、aclnn基础头文件和算子API头文件：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;acl/acl.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;aclnn/aclnn_base.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;aclnn_add_custom.h&quot;</span>
</code></pre></div><p><code>acl/acl.h</code>提供<code>aclrtMalloc</code>、<code>aclrtMemcpy</code>、<code>aclrtSetDevice</code>等运行时接口；<code>aclnn/aclnn_base.h</code>提供<code>aclnnInit</code>、<code>aclnnFinalize</code>、<code>aclOpExecutor</code>等aclnn基础类型和接口；<code>aclnn_add_custom.h</code>是AddCustom算子工程生成的单算子API头文件。</p><h3 id="初始化运行环境">初始化运行环境<a class="header-anchor" href="#初始化运行环境">​</a></h3><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">CHECK_ACL</span><span class="p">(</span><span class="n">aclnnInit</span><span class="p">(</span><span class="nb">nullptr</span><span class="p">));</span>

<span class="k">const</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">deviceId</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="n">CHECK_RTL</span><span class="p">(</span><span class="n">aclrtSetDevice</span><span class="p">(</span><span class="n">deviceId</span><span class="p">));</span>

<span class="n">aclrtStream</span><span class="w"> </span><span class="n">stream</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">;</span>
<span class="n">CHECK_RTL</span><span class="p">(</span><span class="n">aclrtCreateStream</span><span class="p">(</span><span class="o">&amp;</span><span class="n">stream</span><span class="p">));</span>
</code></pre></div><p>这一步完成ACL初始化、指定Device，并创建后续算子下发使用的stream。</p><h3 id="准备输入输出数据并创建Tensor">准备输入输出数据并创建Tensor<a class="header-anchor" href="#准备输入输出数据并创建Tensor">​</a></h3><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 申请内存存放算子的输入输出</span>
<span class="n">CHECK_RTL</span><span class="p">(</span><span class="n">aclrtMalloc</span><span class="p">(</span><span class="o">&amp;</span><span class="n">input0DeviceMem</span><span class="p">,</span><span class="w"> </span><span class="n">bufferSize</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_MEM_MALLOC_HUGE_FIRST</span><span class="p">));</span>
<span class="n">CHECK_RTL</span><span class="p">(</span><span class="n">aclrtMalloc</span><span class="p">(</span><span class="o">&amp;</span><span class="n">input1DeviceMem</span><span class="p">,</span><span class="w"> </span><span class="n">bufferSize</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_MEM_MALLOC_HUGE_FIRST</span><span class="p">));</span>
<span class="n">CHECK_RTL</span><span class="p">(</span><span class="n">aclrtMalloc</span><span class="p">(</span><span class="o">&amp;</span><span class="n">outputDeviceMem</span><span class="p">,</span><span class="w"> </span><span class="n">bufferSize</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_MEM_MALLOC_HUGE_FIRST</span><span class="p">));</span>
<span class="c1">// 传输数据</span>
<span class="n">CHECK_RTL</span><span class="p">(</span><span class="n">aclrtMemcpy</span><span class="p">(</span><span class="n">input0DeviceMem</span><span class="p">,</span><span class="w"> </span><span class="n">bufferSize</span><span class="p">,</span><span class="w"> </span><span class="n">input0Host</span><span class="p">.</span><span class="n">data</span><span class="p">(),</span>
<span class="w">                      </span><span class="n">bufferSize</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_MEMCPY_HOST_TO_DEVICE</span><span class="p">));</span>
<span class="n">CHECK_RTL</span><span class="p">(</span><span class="n">aclrtMemcpy</span><span class="p">(</span><span class="n">input1DeviceMem</span><span class="p">,</span><span class="w"> </span><span class="n">bufferSize</span><span class="p">,</span><span class="w"> </span><span class="n">input1Host</span><span class="p">.</span><span class="n">data</span><span class="p">(),</span>
<span class="w">                      </span><span class="n">bufferSize</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_MEMCPY_HOST_TO_DEVICE</span><span class="p">));</span>

<span class="kt">int64_t</span><span class="w"> </span><span class="n">shape</span><span class="p">[]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span><span class="n">count</span><span class="p">};</span>
<span class="kt">uint64_t</span><span class="w"> </span><span class="n">shapeNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="c1">// 创建tensor</span>
<span class="n">aclTensor</span><span class="w"> </span><span class="o">*</span><span class="n">input0</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">aclCreateTensor</span><span class="p">(</span><span class="n">shape</span><span class="p">,</span><span class="w"> </span><span class="n">shapeNum</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_FLOAT</span><span class="p">,</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span>
<span class="w">                                    </span><span class="n">ACL_FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">shape</span><span class="p">,</span><span class="w"> </span><span class="n">shapeNum</span><span class="p">,</span><span class="w"> </span><span class="n">input0DeviceMem</span><span class="p">);</span>
<span class="n">aclTensor</span><span class="w"> </span><span class="o">*</span><span class="n">input1</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">aclCreateTensor</span><span class="p">(</span><span class="n">shape</span><span class="p">,</span><span class="w"> </span><span class="n">shapeNum</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_FLOAT</span><span class="p">,</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span>
<span class="w">                                    </span><span class="n">ACL_FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">shape</span><span class="p">,</span><span class="w"> </span><span class="n">shapeNum</span><span class="p">,</span><span class="w"> </span><span class="n">input1DeviceMem</span><span class="p">);</span>
<span class="n">aclTensor</span><span class="w"> </span><span class="o">*</span><span class="n">output</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">aclCreateTensor</span><span class="p">(</span><span class="n">shape</span><span class="p">,</span><span class="w"> </span><span class="n">shapeNum</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_FLOAT</span><span class="p">,</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span>
<span class="w">                                    </span><span class="n">ACL_FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">shape</span><span class="p">,</span><span class="w"> </span><span class="n">shapeNum</span><span class="p">,</span><span class="w"> </span><span class="n">outputDeviceMem</span><span class="p">);</span>
</code></pre></div><h3 id="调用两段式接口">调用两段式接口<a class="header-anchor" href="#调用两段式接口">​</a></h3><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 计算workspace大小并申请内存</span>
<span class="kt">uint64_t</span><span class="w"> </span><span class="n">workspaceSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="n">aclOpExecutor</span><span class="w"> </span><span class="o">*</span><span class="n">executor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">;</span>
<span class="n">CHECK_ACL</span><span class="p">(</span><span class="n">aclnnAddCustomGetWorkspaceSize</span><span class="p">(</span><span class="n">input0</span><span class="p">,</span><span class="w"> </span><span class="n">input1</span><span class="p">,</span><span class="w"> </span><span class="n">output</span><span class="p">,</span>
<span class="w">                                         </span><span class="o">&amp;</span><span class="n">workspaceSize</span><span class="p">,</span><span class="w"> </span><span class="o">&amp;</span><span class="n">executor</span><span class="p">));</span>

<span class="kt">void</span><span class="w"> </span><span class="o">*</span><span class="n">workspaceDeviceMem</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">;</span>
<span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">workspaceSize</span><span class="w"> </span><span class="o">&gt;</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">CHECK_RTL</span><span class="p">(</span><span class="n">aclrtMalloc</span><span class="p">(</span><span class="o">&amp;</span><span class="n">workspaceDeviceMem</span><span class="p">,</span><span class="w"> </span><span class="n">workspaceSize</span><span class="p">,</span>
<span class="w">                          </span><span class="n">ACL_MEM_MALLOC_HUGE_FIRST</span><span class="p">));</span>
<span class="p">}</span>
<span class="c1">// 执行算子</span>
<span class="n">CHECK_ACL</span><span class="p">(</span><span class="n">aclnnAddCustom</span><span class="p">(</span><span class="n">workspaceDeviceMem</span><span class="p">,</span><span class="w"> </span><span class="n">workspaceSize</span><span class="p">,</span><span class="w"> </span><span class="n">executor</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="p">));</span>
<span class="c1">// 同步等待</span>
<span class="n">CHECK_RTL</span><span class="p">(</span><span class="n">aclrtSynchronizeStream</span><span class="p">(</span><span class="n">stream</span><span class="p">));</span>
</code></pre></div><p>第一段接口返回<code>workspaceSize</code>后，调用程序需要按需申请Device侧workspace内存。第二段接口负责下发算子计算，随后通过<code>aclrtSynchronizeStream</code>等待计算完成。</p><h3 id="拷贝结果并释放资源">拷贝结果并释放资源<a class="header-anchor" href="#拷贝结果并释放资源">​</a></h3><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">CHECK_RTL</span><span class="p">(</span><span class="n">aclrtMemcpy</span><span class="p">(</span><span class="n">outputHost</span><span class="p">.</span><span class="n">data</span><span class="p">(),</span><span class="w"> </span><span class="n">bufferSize</span><span class="p">,</span><span class="w"> </span><span class="n">outputDeviceMem</span><span class="p">,</span>
<span class="w">                      </span><span class="n">bufferSize</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_MEMCPY_DEVICE_TO_HOST</span><span class="p">));</span>

<span class="n">aclDestroyTensor</span><span class="p">(</span><span class="n">input0</span><span class="p">);</span>
<span class="n">aclDestroyTensor</span><span class="p">(</span><span class="n">input1</span><span class="p">);</span>
<span class="n">aclDestroyTensor</span><span class="p">(</span><span class="n">output</span><span class="p">);</span>
<span class="n">aclDestroyAclOpExecutor</span><span class="p">(</span><span class="n">executor</span><span class="p">);</span>

<span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">workspaceDeviceMem</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">aclrtFree</span><span class="p">(</span><span class="n">workspaceDeviceMem</span><span class="p">);</span>
<span class="p">}</span>
<span class="n">aclrtFree</span><span class="p">(</span><span class="n">input0DeviceMem</span><span class="p">);</span>
<span class="n">aclrtFree</span><span class="p">(</span><span class="n">input1DeviceMem</span><span class="p">);</span>
<span class="n">aclrtFree</span><span class="p">(</span><span class="n">outputDeviceMem</span><span class="p">);</span>

<span class="n">CHECK_RTL</span><span class="p">(</span><span class="n">aclrtDestroyStream</span><span class="p">(</span><span class="n">stream</span><span class="p">));</span>
<span class="n">CHECK_RTL</span><span class="p">(</span><span class="n">aclrtResetDevice</span><span class="p">(</span><span class="n">deviceId</span><span class="p">));</span>
<span class="n">aclnnFinalize</span><span class="p">();</span>
</code></pre></div><p>使用<code>aclCreateTensor</code>创建的Tensor需要调用<code>aclDestroyTensor</code>释放；第一段接口返回的<code>executor</code>需要调用<code>aclDestroyAclOpExecutor</code>释放；Device内存和stream也需要在程序结束前释放。</p><h2 id="编译与运行">编译与运行<a class="header-anchor" href="#编译与运行">​</a></h2><h3 id="CMakeLists.txt关键配置">CMakeLists.txt关键配置<a class="header-anchor" href="#CMakeLists.txt关键配置">​</a></h3><p>算子编译部署后，会生成单算子调用的头文件<code>aclnn_&lt;op&gt;.h</code>和算子API库。算子包部署场景通常链接<code>libcust_opapi.so</code>；动态库或静态库编译场景可参考<a href="../compilation_and_deployment/dynamic_static_lib_compilation.html">算子动态库和静态库编译</a>，通过<code>find_package</code>导入算子库或按实际路径直接链接。</p><p>编译算子调用程序时，需要在头文件的搜索路径include_directories中增加单算子调用的头文件目录，便于找到该头文件；同时需要链接cust_opapi动态库并在库文件的搜索路径link_directories中增加libcust_opapi.so所在目录。</p><ul><li><p>在头文件的搜索路径include_directories中增加单算子调用的头文件目录。以下样例仅为参考，请根据头文件的实际目录位置进行设置。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>target_include_directories(execute_add_op PRIVATE
    $ENV{ASCEND_HOME_PATH}/include
    $ENV{ASCEND_OPP_PATH}/vendors/\${VENDOR_NAME}/op_api/include
)
</code></pre></div></li><li><p>链接cust_opapi链接库。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>target_link_libraries(execute_add_op PRIVATE
    cust_opapi
    nnopbase
    acl_rt
)
</code></pre></div></li><li><p>在库文件的搜索路径link_directories中增加libcust_opapi.so所在目录。以下样例仅为参考，请根据库文件的实际目录位置进行设置。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>target_link_directories(execute_add_op PRIVATE
    $ENV{ASCEND_HOME_PATH}/lib64
    $ENV{ASCEND_OPP_PATH}/vendors/\${VENDOR_NAME}/op_api/lib
)
</code></pre></div></li></ul><h3 id="编译运行步骤">编译运行步骤<a class="header-anchor" href="#编译运行步骤">​</a></h3><ol><li><p>在运行环境上设置环境变量，配置单算子验证程序编译依赖的头文件与库文件路径：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">source</span><span class="w"> </span>/usr/local/Ascend/cann/set_env.sh
<span class="c1"># &lt;vendor_name&gt;需替换为算子工程CMakePresets.json中的vendor_name</span>
<span class="nb">export</span><span class="w"> </span><span class="nv">VENDOR_NAME</span><span class="o">=</span>&lt;vendor_name&gt;
<span class="c1"># 配置自定义算子包环境变量</span>
<span class="c1"># 如果是run包执行</span>
<span class="nb">export</span><span class="w"> </span><span class="nv">LD_LIBRARY_PATH</span><span class="o">=</span><span class="si">\${</span><span class="nv">ASCEND_OPP_PATH</span><span class="si">}</span>/vendors/<span class="si">\${</span><span class="nv">VENDOR_NAME</span><span class="si">}</span>/op_api/lib/:<span class="si">\${</span><span class="nv">LD_LIBRARY_PATH</span><span class="si">}</span>
<span class="c1"># 如果是动态库或者静态库则执行以下命令，其中\${CMAKE_INSTALL_PREFIX}需要换成自定义算子包路径的绝对路径</span>
<span class="nb">export</span><span class="w"> </span><span class="nv">LD_LIBRARY_PATH</span><span class="o">=</span><span class="si">\${</span><span class="nv">CMAKE_INSTALL_PREFIX</span><span class="si">}</span>/lib/:<span class="si">\${</span><span class="nv">LD_LIBRARY_PATH</span><span class="si">}</span>
</code></pre></div></li><li><p>编译样例工程，生成单算子验证可执行文件。</p><ol><li><p>切换到样例工程根目录，然后在样例工程根目录下执行如下命令创建目录用于存放编译文件，例如<code>build</code>。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>mkdir -p build
</code></pre></div></li><li><p>进入build目录，执行cmake编译命令，生成编译文件。</p><p>命令示例如下所示：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>cd build
cmake ../ -DCMAKE_SKIP_RPATH=TRUE
</code></pre></div></li><li><p>执行如下命令，生成可执行文件。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>make
</code></pre></div><p>可执行文件生成位置由调用工程的CMakeLists.txt决定。未设置输出目录时，通常生成在<code>build</code>目录下；如果调用工程设置了<code>RUNTIME_OUTPUT_DIRECTORY</code>，请按实际配置路径查找。</p></li></ol></li><li><p>在运行环境中配置运行依赖，并执行<code>execute_add_op</code>文件：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>\`\`\`
# 以下路径仅为示例，请替换为实际生成的可执行文件路径
./build/execute_add_op
\`\`\`

如果有\`test pass\`，表明执行成功。
</code></pre></div></li></ol><h2 id="常见问题">常见问题<a class="header-anchor" href="#常见问题">​</a></h2><p><strong>找不到<code>aclnn_add_custom.h</code></strong></p><p>先确认<code>VENDOR_NAME</code>是否与算子工程<code>CMakePresets.json</code>中的<code>vendor_name</code>一致，再确认算子包是否已经安装：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>ls<span class="w"> </span><span class="nv">$ASCEND_OPP_PATH</span>/vendors/<span class="si">\${</span><span class="nv">VENDOR_NAME</span><span class="si">}</span>/op_api/include/aclnn_add_custom.h
</code></pre></div><p>如果使用指定目录安装，需要检查<code>&lt;path&gt;/vendors/\${VENDOR_NAME}/op_api/include/aclnn_add_custom.h</code>。</p><p><strong>运行时报<code>libcust_opapi.so: cannot open shared object file</code></strong></p><p>说明运行时动态库搜索路径中没有自定义算子API库。设置：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">export</span><span class="w"> </span><span class="nv">LD_LIBRARY_PATH</span><span class="o">=</span><span class="si">\${</span><span class="nv">ASCEND_OPP_PATH</span><span class="si">}</span>/vendors/<span class="si">\${</span><span class="nv">VENDOR_NAME</span><span class="si">}</span>/op_api/lib/:<span class="si">\${</span><span class="nv">LD_LIBRARY_PATH</span><span class="si">}</span>
</code></pre></div><h2 id="进阶：API参数命名规则">进阶：API参数命名规则<a class="header-anchor" href="#进阶：API参数命名规则">​</a></h2><p>首次跑通AddCustom调用时，可以先跳过本节。aclnn接口入参由算子原型注册信息转换生成，输入、输出、属性等原型定义会映射为C接口中的参数；具体参数类型和名称以实际生成的<code>aclnn_&lt;op&gt;.h</code>为准。开发包含可选输入、多输出、属性或数据依赖输入的算子时，可参考以下规则确认生成接口的参数名称。</p><p><strong>aclnn_Xxx_GetWorkspaceSize</strong>接口的输入输出参数生成规则如下：</p><ul><li><p>可选输入的命名增加Optional后缀。如下样例中，x是可选输入。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>aclnnStatus aclnnXxxGetWorkspaceSize(const aclTensor *xOptional, ..., aclTensor *out, uint64_t *workspaceSize, aclOpExecutor **executor);
</code></pre></div></li><li><p>输入输出同名、使用同一个Tensor承载的情况下，生成的aclnn接口中只保留input参数，同时去掉input的const修饰，并以Ref作为后缀。如下样例中，原型定义input、output都定义为x，xRef既作为输入，又作为输出。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>aclnnStatus aclnnXxxGetWorkspaceSize(aclTensor *xRef, ..., uint64_t *workspaceSize, aclOpExecutor **executor);
</code></pre></div></li><li><p>如果仅有一个输出，输出参数命名为out；如果存在多个输出，每个输出后面都以Out作为后缀。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 仅有一个输出
aclnnStatus aclnnXxxGetWorkspaceSize(const aclTensor *src, ..., aclTensor *out, uint64_t *workspaceSize, aclOpExecutor **executor);
// 存在多个输出
aclnnStatus aclnnXxxGetWorkspaceSize(const aclTensor *src, ..., aclTensor *yOut, aclTensor *y1Out, ..., uint64_t *workspaceSize, aclOpExecutor **executor);
</code></pre></div></li><li><p>如果算子包含属性，则属性参数的位置介于输入和输出之间。如下示例中，x是算子输入，negativeSlope是算子属性，out是算子输出。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>aclnnStatus aclnnXxxGetWorkspaceSize(const aclTensor *x, double negativeSlope, aclTensor *out, uint64_t *workspaceSize, aclOpExecutor **executor);
</code></pre></div></li></ul><p>当算子原型注册时使用ValueDepend接口标识输入为数据依赖输入时，会额外生成一个API，该API支持值依赖场景输入数据为空的一阶段计算。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>aclnnStatus aclnnXxxTensorGetWorkspaceSize(const aclTensor *src, ..., aclTensor *out, uint64_t *workspaceSize, aclOpExecutor **executor);
</code></pre></div><p><strong>在aclnn_Xxx_TensorGetWorkspaceSize</strong>中，<strong>aclnn_Xxx_GetWorkspaceSize</strong>参数的数据类型（aclIntArray、aclFloatArray和aclBoolArray）将被转换为aclTensor数据类型，其他输入输出参数生成规则与<strong>aclnn_Xxx_GetWorkspaceSize</strong>一致。如下示例中，x0、x1、x2是算子声明为数据依赖的输入，数据类型分别为DT_INT64、DT_BOOL、DT_FLOAT，out是算子输出。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>aclnnStatus aclnnXxxGetWorkspaceSize(const aclIntArray *x0, const aclBoolArray *x1, const aclFloatArray *x2, aclTensor *out, uint64_t *workspaceSize, aclOpExecutor **executor);
aclnnStatus aclnnXxxTensorGetWorkspaceSize(const aclTensor *x0, const aclTensor *x1, const aclTensor *x2, aclTensor *out, uint64_t *workspaceSize, aclOpExecutor **executor);
</code></pre></div><h2 id="相关文档">相关文档<a class="header-anchor" href="#相关文档">​</a></h2><ul><li><a href="../aclnn_quick_start.html">快速入门</a> — 创建并跑通AddCustom算子工程。</li><li><a href="../compilation_and_deployment/basic_process.html">算子工程编译</a> — 部署算子包并查看部署目录。</li></ul></article></div>`,1)])])}const u=a(e,[["render",t]]);export{_ as __pageData,u as default};
